using System.Reflection;
using System.Runtime.InteropServices;
using System.Collections.Concurrent;
using System.Text.Json;
using System.Text.RegularExpressions;

class CatalogueService {
 const string Modules="/opt/usr/apps/com.samsung.tv.SAFCommonPlugin/shared/lib/netcoreapp2.0/";
 readonly SemaphoreSlim network=new(1);readonly ConcurrentDictionary<string,string> categories=new();
 readonly ConcurrentDictionary<string,JsonElement> known=new(),details=new();
 readonly ConcurrentDictionary<string,InstallState> installations=new();
 object? connector;Type? connectorType;JsonElement? home,snapshot;DateTime homeTime;bool usingSnapshot,liveBlocked;string captured="";
 record InstallState(string state,int progress,string message);
 [DllImport("libvconf.so.0")] static extern IntPtr vconf_get_str(string key);
 [DllImport("libc.so.6")] static extern void free(IntPtr p);
 [DllImport("libcapi-appfw-app-control.so.0")] static extern int app_control_create(out IntPtr handle);
 [DllImport("libcapi-appfw-app-control.so.0")] static extern int app_control_add_extra_data(IntPtr handle,string key,string value);
 [DllImport("libcapi-appfw-app-control.so.0")] static extern int app_control_destroy(IntPtr handle);
 [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate void InstallCallback(string id,uint type,int progress,int result,IntPtr data);
 [DllImport("/usr/lib/libwas_manager_api.so")] static extern int was_install_app(IntPtr handle,InstallCallback callback,IntPtr data);
 readonly InstallCallback installCallback;
 public CatalogueService(){installCallback=OnInstallEvent;AppDomain.CurrentDomain.AssemblyResolve+=Resolve;}
 static Assembly? Resolve(object? sender,ResolveEventArgs args){string name=new AssemblyName(args.Name).Name+".dll";foreach(var dir in new[]{Modules,"/opt/usr/apps/com.samsung.tv.SAFCommonPlugin/bin/","/usr/share/dotnet.tizen/framework/","/usr/share/dotnet.tizen/tvappapi/"}){string p=Path.Combine(dir,name);if(File.Exists(p))return Assembly.LoadFrom(p);}return null;}
 static string Setting(string key){var p=vconf_get_str(key);try{return Marshal.PtrToStringUTF8(p)??"";}finally{if(p!=IntPtr.Zero)free(p);}}
 static string Str(JsonElement x,string key)=>x.ValueKind==JsonValueKind.Object&&x.TryGetProperty(key,out var v)?v.ValueKind==JsonValueKind.String?v.GetString()??"":v.ToString():"";
 static int Num(JsonElement x,string key,int fallback)=>int.TryParse(Str(x,key),out var n)?n:fallback;
 static IEnumerable<JsonElement> Array(JsonElement x,string key)=>x.ValueKind==JsonValueKind.Object&&x.TryGetProperty(key,out var v)&&v.ValueKind==JsonValueKind.Array?v.EnumerateArray():Enumerable.Empty<JsonElement>();
 string Query()=>"?modelid="+Uri.EscapeDataString(Setting("db/comss/modelid"))+"&countrycode="+Uri.EscapeDataString(Setting("db/comss/countrycode"))+"&vdlangcode="+Uri.EscapeDataString(Setting("db/menu_widget/language").Split('.')[0])+"&resolution=1080&firmcode="+Uri.EscapeDataString(Setting("db/comss/infolinkversion"))+"&timestamp="+DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
 JsonElement Saved(string path,string extra){
  if(snapshot==null){var file=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../res/catalogue-snapshot.json"));if(!File.Exists(file))throw new InvalidOperationException("Live catalogue authentication is unavailable. No saved catalogue is installed.");using var doc=JsonDocument.Parse(File.ReadAllText(file));snapshot=doc.RootElement.Clone();captured=Str(snapshot.Value,"capturedAt");}
  usingSnapshot=true;var data=snapshot.Value;
  if(path=="apps/marketplace/v3/categories/home")return data.GetProperty("home");
  if(path.StartsWith("store/marketplace/v2/categories/",StringComparison.Ordinal)){string id=path.Split('/')[4];if(!data.GetProperty("categories").TryGetProperty(id,out var apps))throw new InvalidOperationException("This category is not available in the saved catalogue.");int page=1;var match=Regex.Match(extra,@"[&?]page=(\d+)");if(match.Success)page=int.Parse(match.Groups[1].Value);return JsonSerializer.SerializeToElement(new{stat="ok",apps=new[]{new{page=page.ToString(),lastPage=Math.Max(1,(apps.GetArrayLength()+19)/20).ToString(),total=apps.GetArrayLength().ToString(),items=apps.EnumerateArray().Skip((page-1)*20).Take(20).Select(x=>x.Clone()).ToArray()}}});}
  if(path.StartsWith("store/marketplace/v2/detail/",StringComparison.Ordinal)){string id=path.Split('/').Last();if(!known.TryGetValue(id,out var app))throw new InvalidOperationException("Choose an app from the catalogue first.");return JsonSerializer.SerializeToElement(new{stat="ok",apps=new[]{app}});}
  throw new InvalidOperationException("Saved catalogue unavailable for this request.");
 }
 JsonElement Get(string path,string extra=""){
  if(liveBlocked)return Saved(path,extra);
  if(connector==null){connectorType=Assembly.LoadFrom(Modules+"SAFRestPlugin.dll").GetType("Tizen.TV.Service.RestPlugin.RestPlugin",true)!;connector=Activator.CreateInstance(connectorType)!;connectorType.GetMethod("Init")!.Invoke(connector,null);connectorType.GetMethod("SetTimeout")!.Invoke(connector,new object[]{8000,1});connectorType.GetMethod("SetSamsungDomain")!.Invoke(connector,new object[]{false});connectorType.GetMethod("SetHeader")!.Invoke(connector,new object[]{"X-VD-Caller","HomeCtl001.Control"});}
  string response=(string)connectorType!.GetMethod("SendRequestSyncWithoutResponseLog")!.Invoke(connector,new object[]{"https://osb-apps-v2.samsungqbe.com/"+path+Query()+extra,"GET"})!;
  using var outer=JsonDocument.Parse(response);if(Num(outer.RootElement,"status",0)!=200){string code="";try{var failure=outer.RootElement.GetProperty("data");using var parsed=JsonDocument.Parse(failure.ValueKind==JsonValueKind.String?failure.GetString()!:failure.GetRawText());code=Str(parsed.RootElement.GetProperty("rsp").GetProperty("err"),"code");}catch{}if(!Regex.IsMatch(code,@"^\d{1,12}$"))code="unknown";if(code=="1144001")liveBlocked=true;return Saved(path,extra);}
  var data=outer.RootElement.GetProperty("data");using var body=JsonDocument.Parse(data.ValueKind==JsonValueKind.String?data.GetString()!:data.GetRawText());var rsp=body.RootElement.GetProperty("rsp");if(Str(rsp,"stat")!="ok")throw new InvalidOperationException("The app catalogue is temporarily unavailable.");return rsp.Clone();
 }
 JsonElement Home(){if(home==null||DateTime.UtcNow-homeTime>TimeSpan.FromMinutes(5)){home=Get("apps/marketplace/v3/categories/home","&start=1&rows=20&numapps=100");homeTime=DateTime.UtcNow;categories.Clear();foreach(var group in Array(home.Value,"categories"))if(Str(group,"type")=="GENRE"||Str(group,"type")=="CATEGORY")foreach(var c in Array(group,"items")){string id=Str(c,"categoryId");if(Regex.IsMatch(id,@"^[\w.-]{1,60}$"))categories[id]=Str(c,"title");}}return home.Value;}
 static string Icon(JsonElement app){var url=Str(app,"icon").Replace("{w}","250").Replace("{h}","250");return Uri.TryCreate(url,UriKind.Absolute,out var uri)&&uri.Scheme=="https"&&(uri.Host=="d1oxlq5h9kq8q5.cloudfront.net"||uri.Host=="d2px1x70oyj1za.cloudfront.net"||uri.Host=="store.samsungcloudcdn.com")?url:"";}
 object App(JsonElement app,string categoryId,string category){string id=Str(app,"id");known[id]=app.Clone();return new{id,title=Str(app,"title"),categoryId,category,icon=Icon(app)};}
 object List(JsonElement data){var start=Home();var cats=categories.OrderBy(x=>x.Value).Select(x=>new{id=x.Key,name=x.Value}).ToArray();string category=Str(data,"category");int page=Math.Clamp(Num(data,"page",1),1,10000);
  if(category==""){var seen=new HashSet<string>();var apps=new List<object>();foreach(var group in Array(start,"categories"))if(Str(group,"type")=="APPLIST")foreach(var app in Array(group,"items"))if(seen.Add(Str(app,"id")))apps.Add(App(app,"featured",Str(group,"title")));return new{live=!usingSnapshot,cached=usingSnapshot,updated=captured,apps,categories=cats,page=1,pages=1,total=apps.Count,featured=true};}
  if(!categories.TryGetValue(category,out var title))throw new InvalidOperationException("Choose an available app category.");var rsp=Get("store/marketplace/v2/categories/"+Uri.EscapeDataString(category)+"/apps","&page="+page+"&sort=releasedate&perpage=20");var groupPage=Array(rsp,"apps").FirstOrDefault();if(groupPage.ValueKind==JsonValueKind.Undefined)throw new InvalidOperationException("The category returned no app list.");return new{live=!usingSnapshot,cached=usingSnapshot,updated=captured,apps=Array(groupPage,"items").Select(app=>App(app,category,title)).ToArray(),categories=cats,page=Num(groupPage,"page",page),pages=Num(groupPage,"lastPage",1),total=Num(groupPage,"total",0),featured=false};
 }
 object Detail(string id){if(!known.ContainsKey(id))throw new InvalidOperationException("Choose an app from the catalogue first.");var rsp=Get("store/marketplace/v2/detail/"+Uri.EscapeDataString(id));var app=Array(rsp,"apps").FirstOrDefault();if(Str(app,"id")!=id)throw new InvalidOperationException("App details are unavailable.");details[id]=app.Clone();return new{id,title=Str(app,"title"),description=usingSnapshot?"Listed in the saved catalogue. Live app details and installation are currently unavailable.":Str(app,"description"),canInstall=!usingSnapshot,category=Str(app,"category"),icon=Icon(app),size=long.TryParse(Str(app,"fileSize"),out var size)?Math.Round(size/1048576d,1)+" MB":"",version=Str(app,"version"),price=Str(app,"price")};}
 void OnInstallEvent(string id,uint type,int progress,int result,IntPtr unused){if(!installations.ContainsKey(id))return;string state=type==110&&result==0?"complete":type==103||type==106||type==108||type==111||result!=0?"failed":type==104||type==130?"cancelled":"installing";installations[id]=new(state,Math.Clamp(progress,0,100),state=="complete"?"Installed":state=="failed"?"The monitor could not install this app ("+result+").":state=="cancelled"?"Installation cancelled.":"Installing…");}
 object Install(string id){if(liveBlocked||usingSnapshot)throw new InvalidOperationException("Installation requires the live catalogue connection. No app was installed.");if(!details.TryGetValue(id,out var info))throw new InvalidOperationException("Open the app details before installing.");string price=Str(info,"price");if(price!=""&&price!="0"&&price!="0.0"&&!price.Equals("free",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Purchases require account approval. No purchase was made.");if(installations.TryGetValue(id,out var prior)&&prior.state=="installing")return prior;
  if(app_control_create(out var handle)!=0)throw new InvalidOperationException("App installation is unavailable.");try{if(app_control_add_extra_data(handle,"id",id)!=0)throw new InvalidOperationException("The monitor rejected the app selection.");installations[id]=new("installing",0,"Installation requested…");int code=was_install_app(handle,installCallback,IntPtr.Zero);if(code!=0){installations.TryRemove(id,out _);throw new InvalidOperationException("The monitor did not allow installation ("+code+"). No installation was confirmed.");}return installations[id];}finally{app_control_destroy(handle);}
 }
 public async Task<object> Handle(string route,JsonElement data){string id=Str(data,"id");if(route=="catalogue/install")return Install(id);if(route=="catalogue/status")return installations.TryGetValue(id,out var state)?state:new InstallState("unknown",0,"No installation is being tracked.");await network.WaitAsync();try{return await Task.Run(()=>route switch{"catalogue/list"=>List(data),"catalogue/detail"=>Detail(id),_=>throw new InvalidOperationException("Unknown catalogue action.")});}catch(TargetInvocationException){throw new InvalidOperationException("The monitor's app catalogue connector is unavailable.");}finally{network.Release();}}
}
